"""Build offline, source-private, self-contained HSN 180 hierarchy explorer."""
from pathlib import Path
import json,sys,html

def readlines(f):return [json.loads(s) for s in Path(f).open()]

def compact(row,decimation):
    return {'id':row['id'],'tier':row['tier'],'policy':row['chosenPolicy'],
        'train':next(x['trainScore'] for x in row['policyAlternatives'] if x['policy']==row['chosenPolicy']),
        'heldout':next(x['holdoutScore'] for x in row['policyAlternatives'] if x['policy']==row['chosenPolicy']),
        'baseline':row['policyAlternatives'][0]['holdoutScore'],'policies':row['policyAlternatives'],
        'series':[{'year':i+1,'risk':z[0],'uncertainty':z[1],'dissent':z[2],
          'unresolved':z[3],'caught':z[4],'coherence':z[9]} for i,z in enumerate(row['yearlySelected']) if i%decimation==0 or i==179],
        'receipt':row['receiptSha256'],'children':row.get('children',[]),
        'sourceRole':row.get('role'),'v09Receipt':row.get('v09ReceiptSha256'),
        'crossId':row.get('structuralCrossHouseCandidate'),
        'crossBp':row.get('structuralCrossHouseSimilarityBp',0)}

def make(root,source,out):
    root=Path(root);source=json.loads(Path(source).read_text());summary=json.loads((root/'SUMMARY.json').read_text());analysis=json.loads((root/'SYNTHESIS_ANALYSIS.json').read_text());ablation=json.loads((root/'ABLATION_REPORT.json').read_text())
    n=readlines(root/'NODES.jsonl');s=readlines(root/'SPHERES.jsonl');h=readlines(root/'HOUSES.jsonl');m=json.loads((root/'META145.json').read_text())
    content={'report':summary,'analysis':analysis['tiers'],'ablation':{k:v for k,v in ablation.items() if k!='method'},
       'houses':[{'id':k,'name':v['name']} for k,v in source['houses'].items()],
       'rows':[compact(m,1)]+[compact(x,1) for x in h]+[compact(x,6) for x in s]+[compact(x,10) for x in n]}
    byid={x['id']:x for x in content['rows']}
    for row in content['rows']:
        if row['tier']=='NODE':row['name']=source['nodes'][row['id']]['name']
        elif row['tier']=='SPHERE':row['name']=source['spheres'][row['id']]['name']
        elif row['tier']=='HOUSE':row['name']=source['houses'][row['id']]['name']
        else:row['name']='META145 · One synthesis'
    assert len(content['rows'])==1885 and len(byid)==1885
    dump=json.dumps(content,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS HSN-180 · The 1,885-simulation garden</title>
<style>
:root{--bg:#061719;--panel:#10292b;--panel2:#0b2022;--ink:#f2f0df;--muted:#b2c5bd;--line:#335254;--gold:#e1cc8a;--mint:#9be3c0;--violet:#cbaff9;--cyan:#97d4e8}
*{box-sizing:border-box}body{background:radial-gradient(ellipse at 0% 0%,#20433e 0%,transparent 40%),radial-gradient(ellipse at 100% 0%,#2d2646 0%,transparent 40%),var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;margin:0;line-height:1.42}button,input,select{font:inherit}header{max-width:1450px;margin:auto;padding:40px 30px 20px}h1{font-size:clamp(34px,5vw,65px);line-height:1.02;letter-spacing:-.045em;margin:9px 0 18px;font-family:Georgia,serif;font-weight:500}h2{font-family:Georgia,serif;font-weight:500;font-size:26px;margin:0 0 10px}.eyebrow{letter-spacing:.19em;text-transform:uppercase;color:var(--gold);font-size:11px;font-weight:700}.lede{max-width:830px;color:var(--muted);font-size:16px}a{color:var(--mint)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;max-width:1450px;margin:12px auto 24px;padding:0 30px}.metric{background:rgba(16,41,43,.76);border:1px solid var(--line);padding:18px;border-radius:14px}.num{font-size:clamp(23px,3vw,37px);letter-spacing:-.04em;color:var(--mint);font-variant-numeric:tabular-nums}.metric small{color:var(--muted);font-size:12px}.frame{max-width:1450px;margin:auto;display:grid;grid-template-columns:minmax(310px, .86fr) minmax(400px,1.14fr);gap:18px;padding:0 30px 40px}.panel{border:1px solid var(--line);background:rgba(8,30,32,.94);border-radius:18px;padding:20px;min-width:0}.panelhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.slim{color:var(--muted);font-size:12px}.controls{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px}.controls .wide{grid-column:1 / -1}select,input{width:100%;min-width:0;background:#071d20;color:var(--ink);border:1px solid #4b6b69;border-radius:10px;padding:12px;outline-offset:2px}.cardlist{display:grid;gap:7px;max-height:630px;overflow-y:auto;padding-right:4px}.item{cursor:pointer;text-align:left;padding:11px 12px;border:1px solid #315353;border-radius:10px;background:#102d2e;color:var(--ink);transition:background .12s ease}.item:hover,.item.active{background:#214449;border-color:var(--mint)}.item span{display:block}.item .id{font-size:11px;color:var(--gold);letter-spacing:.09em}.item .name{font-size:13px;margin-top:2px}.item .note{font-size:11px;color:var(--muted);margin-top:5px}.pager{display:flex;align-items:center;justify-content:space-between;margin-top:14px;font-size:12px;color:var(--muted)}.pager button{color:var(--ink);background:#173a3d;border:1px solid #4a6d6c;padding:7px 14px;border-radius:8px;cursor:pointer}.pager button:disabled{opacity:.4;cursor:default}.detail-head{border-bottom:1px solid var(--line);padding-bottom:15px;margin-bottom:16px}.detail-head p{margin:3px 0;font-size:14px;color:var(--muted)}.pill{display:inline-block;border:1px solid #527778;color:var(--mint);border-radius:999px;padding:4px 9px;font-size:11px;margin:2px 7px 2px 0}.warn{background:#493423;border:1px solid #806143;color:#ffe1ad;border-radius:10px;padding:12px;font-size:12px;margin:12px 0}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:18px}.stat{background:#0b2023;border:1px solid #31494b;border-radius:10px;padding:12px}.stat strong{display:block;font-size:22px;color:var(--gold);font-variant-numeric:tabular-nums}.stat small{color:var(--muted);font-size:11px}svg{width:100%;height:235px;background:#0b2425;border:1px solid #2d4b50;border-radius:13px;overflow:visible}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:8px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.tablewrap{overflow-x:auto;margin-top:14px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:8px;text-align:left;border-bottom:1px solid #2d4b4a}td.right,th.right{text-align:right;font-variant-numeric:tabular-nums}tr.selected{color:var(--mint);font-weight:700}.smallprint{color:var(--muted);font-size:11px;margin-top:14px;overflow-wrap:anywhere}.foot{max-width:1450px;margin:0 auto;padding:0 30px 45px;color:var(--muted);font-size:13px}.foot strong{color:var(--gold)}@media(max-width:950px){.frame{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.cardlist{max-height:400px}}@media(max-width:540px){header{padding:28px 16px 16px}.frame,.metrics{padding-left:16px;padding-right:16px}.panel{padding:16px}.metrics{grid-template-columns:1fr 1fr}.controls{grid-template-columns:1fr 1fr}.num{font-size:23px}}
</style></head><body>
<header><div class="eyebrow">Atlas ONE / Ariadne v0.7 / simulation laboratory</div><h1>The Garden of<br>1,885 Perspectives</h1><p class="lede">One hundred and eighty <em>synthetic</em> years, from every original knowledge Node through 144 Spheres, 12 Houses and one META145 synthesis. Six finite policy experiments per perspective. The source has an identity; the model has limits.</p></header>
<section class="metrics"><div class="metric"><div class="num">1,728</div><small>Original source Node simulations</small></div><div class="metric"><div class="num">144 + 12 + 1</div><small>True bottom-up perspectives</small></div><div class="metric"><div class="num">2,035,800</div><small>Executed synthetic policy-year updates</small></div><div class="metric"><div class="num">180</div><small>Years per simulation (120 train / 60 held out)</small></div></section>
<main class="frame"><section class="panel"><div class="panelhead"><h2>Navigate perspectives</h2><span id="count" class="slim"></span></div><div class="controls"><label class="wide"><span class="slim">Search name or coordinate</span><input id="search" placeholder="H05.S05.N03 · knowledge graphs" autocomplete="off"></label><label><span class="slim">Perspective tier</span><select id="tier"><option value="NODE">Node</option><option value="SPHERE">Sphere</option><option value="HOUSE">House</option><option value="META145">META145</option></select></label><label><span class="slim">House</span><select id="house"><option value="">All Houses</option></select></label><label class="wide"><span class="slim">Sphere</span><select id="sphere"><option value="">All Spheres</option></select></label></div><div id="list" class="cardlist" aria-live="polite"></div><div class="pager"><button id="prev">Previous</button><span id="pageLabel"></span><button id="next">Next</button></div></section><section class="panel"><div class="detail-head"><div class="eyebrow" id="detailId">META145</div><h2 id="detailName">One synthesis</h2><p id="detailScope"></p><span class="pill">Source-pinned fiction</span><span class="pill">No hosted authority</span></div><div class="two"><div class="stat"><strong id="trainScore"></strong><small>Training objective (years 1–120)</small></div><div class="stat"><strong id="heldScore"></strong><small>Selected policy heldout objective (years 121–180)</small></div><div class="stat"><strong id="baselineScore"></strong><small>Round-robin heldout baseline</small></div><div class="stat"><strong id="policyName"></strong><small>Preselected finite policy</small></div></div><div class="eyebrow">Selected 180-year trace</div><svg id="trend" viewBox="0 0 640 235" role="img" aria-label="Synthetic risk, uncertainty and coherence traces over 180 years"></svg><div class="legend"><span><i class="dot" style="background:#e1cc8a"></i>Risk warning</span><span><i class="dot" style="background:#97d4e8"></i>Uncertainty</span><span><i class="dot" style="background:#9be3c0"></i>Coherence proxy</span></div><div class="eyebrow" style="margin-top:20px">The six declared policy tracks</div><div class="tablewrap"><table><thead><tr><th>Policy</th><th class="right">Train</th><th class="right">Holdout</th><th class="right">Cost</th></tr></thead><tbody id="policies"></tbody></table></div><div class="warn" id="warning">The word “optimal” refers only to a finite, source-identified synthetic training objective. No scientific or human-world outcome has been established.</div><div id="receipt" class="smallprint"></div></section></main>
<div class="foot"><strong>Boundary:</strong> Original HSN names and source record hashes stay in the owner-private archive. Cross-House v0.9 lexical candidates remain unreviewed. No Work-room bodies, Brain, Palace, Imagine, Play, protected source, model weights, current permission grants, CANON or deployments are inferred by this visualization. The first 120 years choose the policy; the last 60 test it. Repeated values in this artificial universe do not constitute evidence of real cognition.</div>
<script type="application/json" id="source-data">__DATA__</script>
<script>
(()=>{'use strict';const db=JSON.parse(document.getElementById('source-data').textContent),all=db.rows;const ids=new Map(all.map(x=>[x.id,x]));const get=id=>document.getElementById(id);let offset=0,current=ids.get('META145');const L=24;
function escape(s){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}
const houseName=id=>db.houses.find(x=>x.id===id)?.name||id;
for(const h of db.houses){const o=document.createElement('option');o.value=h.id;o.textContent=h.id+' — '+h.name;get('house').appendChild(o)}
function spheres(){const h=get('house').value,old=get('sphere').value;get('sphere').innerHTML='<option value="">All Spheres</option>';for(let i=1;i<=12;i++)for(let j=1;j<=12;j++){const id='H'+String(i).padStart(2,'0')+'.S'+String(j).padStart(2,'0');if(h&&!id.startsWith(h+'.'))continue;const o=document.createElement('option');o.value=id;o.textContent=id;get('sphere').appendChild(o)}if([...get('sphere').options].some(x=>x.value===old))get('sphere').value=old;}
function filtered(){let tier=get('tier').value,q=get('search').value.toLowerCase().trim(),house=get('house').value,sphere=get('sphere').value;return all.filter(x=>x.tier===tier&&(!house||x.id.startsWith(house))&&(!sphere||x.id.startsWith(sphere))&&(!q||(x.id+' '+x.name).toLowerCase().includes(q)));}
function renderList(){const data=filtered();offset=Math.max(0,Math.min(offset,Math.max(0,Math.ceil(data.length/L)-1)*L));get('count').textContent=data.length.toLocaleString()+' matching simulations';get('pageLabel').textContent='page '+(Math.floor(offset/L)+1)+' / '+Math.max(1,Math.ceil(data.length/L));get('prev').disabled=offset===0;get('next').disabled=offset+L>=data.length;get('list').innerHTML='';for(const row of data.slice(offset,offset+L)){let b=document.createElement('button');b.className='item'+(row.id===current?.id?' active':'');b.innerHTML='<span class="id">'+escape(row.id)+' / '+escape(row.tier)+'</span><span class="name">'+escape(row.name)+'</span><span class="note">'+escape(row.policy)+' · synthetic heldout '+row.heldout+'</span>';b.onclick=()=>select(row.id);get('list').appendChild(b)}}
function draw(series){const s=get('trend');s.innerHTML='';const mk=(tag,attr)=>{let el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(let [k,v] of Object.entries(attr))el.setAttribute(k,String(v));s.appendChild(el);return el};for(let tick=0;tick<=4;tick++){let y=20+tick*49;mk('line',{x1:28,y1:y,x2:622,y2:y,stroke:'#315355','stroke-width':'1'});mk('text',{x:5,y:y+4,fill:'#9ab8af','font-size':11}).textContent=1000-tick*250}for(const [key,color] of [['risk','#e1cc8a'],['uncertainty','#97d4e8'],['coherence','#9be3c0']]){const path=series.map((z,i)=>((i?'L':'M')+(28+594*(z.year-1)/179).toFixed(2)+','+(216-196*Math.max(0,Math.min(1000,z[key]))/1000).toFixed(2))).join(' ');mk('path',{d:path,fill:'none',stroke:color,'stroke-width':2,'stroke-linejoin':'round'})}mk('text',{x:28,y:229,fill:'#a6c6ba','font-size':11}).textContent='year 1';mk('text',{x:570,y:229,fill:'#a6c6ba','font-size':11}).textContent='year 180'}
function select(id){const x=ids.get(id);if(!x)return;current=x;get('detailId').textContent=id+' / '+x.tier;get('detailName').textContent=x.name;get('detailScope').textContent=x.tier==='NODE'?'Original Ariadne '+(x.sourceRole||'')+' · source-bound perspective':x.tier==='SPHERE'?'12 original Node perspectives, selected 180-year traces':x.tier==='HOUSE'?'12 Sphere perspectives · '+houseName(id):'12 House perspectives merged without overriding dissent';get('trainScore').textContent=x.train;get('heldScore').textContent=x.heldout;get('baselineScore').textContent=x.baseline;get('policyName').textContent=x.policy.replaceAll('_',' ').toLowerCase();draw(x.series);get('policies').innerHTML=x.policies.map(p=>'<tr class="'+(p.policy===x.policy?'selected':'')+'"><td>'+escape(p.policy)+'</td><td class="right">'+p.trainScore+'</td><td class="right">'+p.holdoutScore+'</td><td class="right">'+p.costUnits+'</td></tr>').join('');get('receipt').textContent='Exact local receipt SHA256: '+x.receipt+(x.v09Receipt?' · Verified predecessor SHA256: '+x.v09Receipt:'');const best=x.policies.reduce((a,b)=>b.holdoutScore>a.holdoutScore?b:a);const note=best.policy!==x.policy?'A different policy ('+best.policy+') performed better on the heldout period. The chosen policy was not retuned after this discovery.':'This policy also led on the heldout slice, which is not a guarantee outside this synthetic fixture.';get('warning').textContent=note+' All decisions are source-only simulations; actual Work rights and scientific acceptance are HOLD.';renderList()}
get('tier').onchange=()=>{offset=0;renderList()};get('house').onchange=()=>{offset=0;spheres();renderList()};get('sphere').onchange=()=>{offset=0;renderList()};get('search').oninput=()=>{offset=0;renderList()};get('prev').onclick=()=>{offset-=L;renderList()};get('next').onclick=()=>{offset+=L;renderList()};spheres();get('tier').value='NODE';renderList();select('META145');
})();
</script></body></html>'''
    page=page.replace('__DATA__',dump)
    out=Path(out);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(page)
    print(json.dumps({'path':str(out),'bytes':out.stat().st_size,'nodes':1728,'spheres':144,'houses':12,'meta':1,'allOptions':6,'offline':True},indent=2))

if __name__=='__main__':make(sys.argv[1],sys.argv[2],sys.argv[3])
